"use client";

import { type DragEvent, type HTMLAttributes, type ReactNode, useId, useRef, useState } from "react";
import { cx } from "../utils/cx";
import { Progress } from "./progress";
import { CloseIcon, UploadIcon } from "../icons/interface";

export type FileRejection = { file: File; reason: "type" | "size" | "count" };

export type FileDropzoneProps = Omit<HTMLAttributes<HTMLDivElement>, "onDrop" | "onChange"> & {
  /** Called with the accepted files (from a drop or the file dialog). */
  onFiles: (files: File[]) => void;
  /** Called with files that were refused, and why. */
  onReject?: (rejections: FileRejection[]) => void;
  /** As the `accept` attribute: ".jpg,.png" or "image/*". */
  accept?: string;
  multiple?: boolean;
  /** Largest file, bytes. */
  maxSize?: number;
  /** Most files per drop. */
  maxFiles?: number;
  disabled?: boolean;
  /** The main line. Default "Drop files here, or browse". */
  label?: ReactNode;
  /** The second line (formats and limits). */
  description?: ReactNode;
  name?: string;
};

const matches = (file: File, accept?: string) => {
  if (!accept) return true;
  return accept
    .split(",")
    .map((a) => a.trim().toLowerCase())
    .filter(Boolean)
    .some((a) =>
      a.startsWith(".")
        ? file.name.toLowerCase().endsWith(a)
        : a.endsWith("/*")
          ? file.type.toLowerCase().startsWith(a.slice(0, -1))
          : file.type.toLowerCase() === a,
    );
};

/**
 * A drop target and file picker in one: drag files over it (it responds), or activate it with the keyboard to open the
 * file dialog. Files are validated against `accept`, `maxSize` and `maxFiles`; the rest are reported to `onReject`.
 */
export function FileDropzone({
  onFiles,
  onReject,
  accept,
  multiple = true,
  maxSize,
  maxFiles,
  disabled,
  label = "Drop files here, or browse",
  description,
  name,
  className,
  ...rest
}: FileDropzoneProps) {
  const [dragging, setDragging] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const depth = useRef(0);
  const descId = useId();

  const take = (list: FileList | File[]) => {
    const files = Array.from(list);
    const ok: File[] = [];
    const bad: FileRejection[] = [];
    for (const file of multiple ? files : files.slice(0, 1)) {
      if (!matches(file, accept)) bad.push({ file, reason: "type" });
      else if (maxSize !== undefined && file.size > maxSize) bad.push({ file, reason: "size" });
      else if (maxFiles !== undefined && ok.length >= maxFiles) bad.push({ file, reason: "count" });
      else ok.push(file);
    }
    if (ok.length) onFiles(ok);
    if (bad.length) onReject?.(bad);
  };
  const over = (e: DragEvent) => {
    if (disabled) return;
    e.preventDefault();
  };
  return (
    <div
      {...rest}
      className={cx("hm-dropzone", className)}
      data-dragging={dragging ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      onDragEnter={(e) => {
        if (disabled) return;
        e.preventDefault();
        depth.current++;
        setDragging(true);
      }}
      onDragOver={over}
      onDragLeave={() => {
        depth.current = Math.max(0, depth.current - 1);
        if (!depth.current) setDragging(false);
      }}
      onDrop={(e) => {
        if (disabled) return;
        e.preventDefault();
        depth.current = 0;
        setDragging(false);
        take(e.dataTransfer.files);
      }}
    >
      <button
        type="button"
        className="hm-dropzone-button"
        disabled={disabled}
        aria-describedby={description ? descId : undefined}
        onClick={() => input.current?.click()}
      >
        <UploadIcon className="hm-dropzone-icon" size={26} />
        <span className="hm-dropzone-label">{label}</span>
        {description ? (
          <span id={descId} className="hm-dropzone-description">
            {description}
          </span>
        ) : null}
      </button>
      <input
        ref={input}
        type="file"
        name={name}
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        tabIndex={-1}
        aria-hidden="true"
        className="hm-sr-only"
        onChange={(e) => {
          if (e.target.files) take(e.target.files);
          e.target.value = "";
        }}
      />
    </div>
  );
}

export type FileItemProps = HTMLAttributes<HTMLLIElement> & {
  name: string;
  /** Bytes. */
  size?: number;
  /** 0 to 100 while uploading; omit when idle. */
  progress?: number;
  status?: "ready" | "uploading" | "done" | "error";
  error?: ReactNode;
  onRemove?: () => void;
};

const bytes = (n: number) =>
  n < 1024 ? `${n} B` : n < 1048576 ? `${(n / 1024).toFixed(1)} KB` : `${(n / 1048576).toFixed(1)} MB`;

/** One row of an upload list: name, size, a progress bar while it uploads, and a remove button. */
export function FileItem({
  name,
  size,
  progress,
  status = "ready",
  error,
  onRemove,
  className,
  ...rest
}: FileItemProps) {
  return (
    <li {...rest} className={cx("hm-file-item", className)} data-status={status}>
      <span className="hm-file-meta">
        <span className="hm-file-name">{name}</span>
        <span className="hm-file-size">{error ?? (size !== undefined ? bytes(size) : null)}</span>
      </span>
      {status === "uploading" && progress !== undefined ? (
        <Progress aria-label={`Uploading ${name}`} value={progress} size="sm" />
      ) : null}
      {onRemove ? (
        <button type="button" className="hm-file-remove" aria-label={`Remove ${name}`} onClick={onRemove}>
          <CloseIcon size={12} strokeWidth={1.7} />
        </button>
      ) : null}
    </li>
  );
}
